 static object Begin(string label){Application.runInBackground=true;EditorApplication.isPaused=false;var app=UnityEngine.Object.FindFirstObjectByType<IslandApp>();app.StartCoroutine(Run(label));return new{started=label};}
 static IEnumerator Run(string label){var root=new GameObject("Fixed rendering and memory audit");var raw=JObject.Parse(File.ReadAllText("C:/Users/SHK/island-contact-diorama-20261107/repo/src/lib/generated/unity-nature-map.json"));var map=new JObject{["unityBossMode"]=true,["laneY"]=5000,["bridge"]=raw["bridge"].DeepClone(),["terrain"]=new JObject{["width"]=raw["width"],["height"]=raw["height"],["step"]=raw["step"],["originX"]=raw["originX"],["originZ"]=raw["originZ"],["heights"]=raw["heights"].DeepClone()}};
  float ground=NativeCombatPresentation.UnityGroundHeight(map,3200);var state=new JObject{["bossVisible"]=true,["room"]=1,["hero"]=new JObject{["action"]="stay1"},["mobs"]=new JArray(new JObject{["unityBoss"]=true,["x"]=3500,["y"]=5000,["elevation"]=NativeCombatPresentation.UnityGroundHeight(map,3500),["hp"]=1000,["action"]="idle",["direction"]=new JObject{["x"]=-1,["y"]=0}}),["fx"]=new JArray()};
  var cameraGo=new GameObject("Audit camera");cameraGo.transform.SetParent(root.transform);var camera=cameraGo.AddComponent<Camera>();camera.enabled=false;camera.cullingMask=1<<30;var rig=root.AddComponent<BattleCameraController>();rig.externallyDriven=true;rig.Bind(camera);var texture=new RenderTexture(1080,1170,24);texture.Create();camera.targetTexture=texture;camera.aspect=1080f/1170;var view=root.AddComponent<Battle3DView>();view.assets=Resources.Load<Battle3DAssets>("Battle3DAssets");view.Planar=true;view.HeroHeading=90;view.Build(root.transform,map,camera);view.UpdateEncounter(state,1.2f);rig.SetViewMode(ViewMode.QuarterView,view.BossTarget);rig.ResetPose();var contact=typeof(Battle3DView).GetMethod("UpdateContact");var draws=new List<int>();var passes=new List<int>();
  for(int i=0;i<360;i++){view.BeginFrame(3200);view.Draw("hero","stay1",3200,ground,1,"fixed",-1,0,0,"",0,1.2f);view.UpdateEncounter(state,1.2f);contact?.Invoke(view,new object[]{state,1.2f});rig.SetPose(new Vector3(32,ground/100,0),1,ground/100,0);rig.Tick(1f/60);camera.Render();if(i>=240){draws.Add(UnityStats.drawCalls);passes.Add(UnityStats.setPassCalls);}yield return null;}
  var active=RenderTexture.active;RenderTexture.active=texture;var image=new Texture2D(texture.width,texture.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,image.width,image.height),0,0);image.Apply();File.WriteAllBytes(Dir+"fixed-"+label+".png",image.EncodeToPNG());RenderTexture.active=active;UnityEngine.Object.Destroy(image);
